from __future__ import annotations

from api.operator_console_final_auth_preview import CONSOLE_HTML_V33

FINAL_AUTH_SCRIPT = r"""
<style>
.final-auth{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.final-auth-form{display:grid;grid-template-columns:1fr 160px;gap:10px}.final-auth-form select,.final-auth-form input[type=number],.final-auth-form textarea{width:100%;border:1px solid #cbdced;border-radius:10px;padding:10px;font:inherit;background:#fff}.final-auth-form textarea{grid-column:1/-1;min-height:90px;resize:vertical}.confirm-stack{grid-column:1/-1;display:grid;gap:8px}.confirm-stack label{display:flex;gap:8px;align-items:flex-start;padding:10px;border:1px solid #e2edf8;background:#fbfdff;border-radius:10px}.final-auth-form button{grid-column:1/-1;border:0;border-radius:10px;padding:12px;background:#0b2f61;color:#fff;font-weight:800;cursor:pointer}.final-auth-form button:disabled{opacity:.55;cursor:not-allowed}.health-line{padding:10px;border-radius:10px;margin-bottom:10px}.health-line.ok{background:#f2fbf5;border:1px solid #cfe7d8;color:#147a46}.health-line.bad{background:#fff3e6;border:1px solid #f2dfb8;color:#9a5a00}.final-auth-status{min-height:20px;margin-top:10px;font-size:13px}.final-auth-status.ok{color:#147a46}.final-auth-status.err{color:#b42318}@media(max-width:620px){.final-auth-form{grid-template-columns:1fr}}
</style>
<script>
async function loadFinalAuthorizationControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('final-authorization-control');if(!box){box=document.createElement('section');box.id='final-authorization-control';box.className='final-auth';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Final Read-Only Authorization</h3><div class="muted">Checking manifest and live capability readiness…</div>';try{const [ctxR,healthR]=await Promise.all([fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/execution-authorization-context',{credentials:'same-origin'}),fetch('/operator/api/capabilities',{credentials:'same-origin'})]);if(ctxR.status===401||healthR.status===401){location.href='/operator/login';return}if(!ctxR.ok){const x=await ctxR.json().catch(()=>({}));throw new Error(x.detail||'authorization context unavailable')}if(!healthR.ok)throw new Error('capability health unavailable');const d=await ctxR.json();const h=await healthR.json();if(!d.ready){box.innerHTML=`<h3>Final Read-Only Authorization</h3><div class="muted">Not available: ${esc((d.reason||'not ready').replaceAll('_',' '))}</div>`;return}const p=d.proposed_execution;const target=(h.items||[]).find(x=>x.id===p.capability_id);const healthy=!!(target&&target.healthy===true);const healthText=healthy?`${p.capability_id} is healthy${target.latency_ms!=null?' · '+target.latency_ms+' ms':''}`:`${p.capability_id} is not currently confirmed healthy`;box.innerHTML=`<h3>Final Read-Only Authorization</h3><div class="manifest-warning">This authorization is short-lived and limited to the exact <strong>${esc(p.effect_class)}</strong> manifest. It still does not dispatch or execute anything by itself.</div><div class="health-line ${healthy?'ok':'bad'}">${esc(healthText)}</div><form id="final-auth-form" class="final-auth-form"><select id="final-decision"><option value="authorize_read_only_execution">Authorize read-only execution</option><option value="request_changes">Request changes</option><option value="hold">Hold</option><option value="reject">Reject</option></select><input id="final-ttl" type="number" min="1" max="60" value="15" title="Authorization TTL minutes"><textarea id="final-rationale" placeholder="Rationale for this final disposition"></textarea><div class="confirm-stack"><label><input type="checkbox" id="final-scope"><span>I confirm the exact objective and scope shown in the execution-review manifest.</span></label><label><input type="checkbox" id="final-effects"><span>I confirm the effect class is read-only internal and the prohibited effects remain prohibited.</span></label><label><input type="checkbox" id="final-health" ${healthy?'':'disabled'}><span>I confirm the live capability-health result shown above.</span></label></div><button id="final-submit">Record final disposition</button></form><div id="final-auth-status" class="final-auth-status"></div>`;const decision=box.querySelector('#final-decision');const checks=[box.querySelector('#final-scope'),box.querySelector('#final-effects'),box.querySelector('#final-health')];function sync(){const authorizing=decision.value==='authorize_read_only_execution';checks.forEach((x,i)=>{x.disabled=!authorizing||(i===2&&!healthy);if(!authorizing)x.checked=false})}decision.onchange=sync;sync();box.querySelector('#final-auth-form').addEventListener('submit',async(e)=>{e.preventDefault();const status=box.querySelector('#final-auth-status');const btn=box.querySelector('#final-submit');status.textContent='';status.className='final-auth-status';btn.disabled=true;try{const authorizing=decision.value==='authorize_read_only_execution';const rationale=box.querySelector('#final-rationale').value;if(authorizing&&!healthy)throw new Error('Capability must be healthy before read-only execution can be authorized.');if(authorizing&&!checks.every(x=>x.checked))throw new Error('All three confirmations are required for read-only execution authorization.');if(authorizing&&!rationale.trim())throw new Error('Authorization rationale is required.');const csrf=await loadConsoleCsrf();const body={decision:decision.value,reviewer_label:'operator-console',rationale:rationale,scope_confirmed:authorizing?checks[0].checked:false,effects_confirmed:authorizing?checks[1].checked:false,capability_health_confirmed:authorizing?checks[2].checked:false,ttl_minutes:Number(box.querySelector('#final-ttl').value||15)};const rr=await fetch('/operator/api/execution-reviews/'+encodeURIComponent(d.manifest_id)+'/final-authorization',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify(body)});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Final authorization rejected')}const x=await rr.json();status.textContent=`Disposition recorded: ${x.authorization.state}. Dispatch permitted: false.`;status.className='final-auth-status ok';setTimeout(()=>loadCase(recordId),300)}catch(err){status.textContent=String(err.message||err);status.className='final-auth-status err'}finally{btn.disabled=false}})}catch(err){box.innerHTML=`<h3>Final Read-Only Authorization</h3><div class="muted">${esc(err.message||'Unavailable.')}</div>`}}
const _v33LoadCase=loadCase;loadCase=async function(id){await _v33LoadCase(id);await loadFinalAuthorizationControl(id)};setTimeout(()=>{if(selected)loadFinalAuthorizationControl(selected)},1400);
</script>
"""

CONSOLE_HTML_V34 = CONSOLE_HTML_V33.replace("</body>", FINAL_AUTH_SCRIPT + "</body>")
